import React, {
    useEffect,
    useCallback,
    useRef
} from 'react';

import {
    View,
    FlatList,
    Text
} from 'react-native';

import { useContexState } from '../../hooks/context';
import { useLoadPage } from '../../hooks/loadPage';

import { ListFooter } from '../../components/ListFooter';
import { ListHeader } from '../../components/ListHeader';
import { ListItem } from '../../components/ListItem';

import { styles } from './styles';

export function RenderList() {
    const { listData, getList, responceArray, sortNumber, rewindPage } = useContexState();

    const { LoadPage } = useLoadPage();

    const refContainer = useRef<FlatList>(null);
    const firstCard = listData[0]?.firstCard;
    const responceNumber = responceArray[0]?.number


    useEffect(() => {
        if (sortNumber !== 'default') {
            if (firstCard) {
                refContainer.current?.scrollToIndex({
                    index: 0,
                    animated: false,
                });
            } else {
                LoadPage();
            }
        } else {
            if (responceNumber) {
                refContainer.current?.scrollToIndex({
                    index: 0,
                    animated: false,
                });
            } else {
                LoadPage();
            }
        }
    }, [firstCard, responceNumber]);

    const renderItem = useCallback(
        ({ item }) =>
            <ListItem data={item} list={getList} />,
        [getList]
    );

    const keyExtractor = useCallback(
        (item) => item.id.toString(), []
    );



    function SortNumberSelect() {
        if (sortNumber === 'default') { return listData };

        if (rewindPage) {
            return listData.map((i, index) => {
                return {
                    firstCard: responceArray.sort((x, y) => x.number - y.number)[index]?.number,
                    id: String(index)
                };
            })
        } else {
            return listData.map((i, index) => {
                return {
                    firstCard: responceArray.sort((x, y) => x.number - y.number)[index]?.number,
                    id: String(index)
                };
            })
        }
    }

    return (
        <View style={styles.listContainer}>
            <FlatList
                contentContainerStyle={{ alignItems: 'center' }}
                removeClippedSubviews={false}
                viewabilityConfig={{
                    viewAreaCoveragePercentThreshold: 10,
                }}
                ref={refContainer}
                numColumns={6}
                initialNumToRender={10}
                key="list"
                data={SortNumberSelect()}
                windowSize={80}
                showsVerticalScrollIndicator={false}
                renderItem={renderItem}
                keyExtractor={keyExtractor}
                updateCellsBatchingPeriod={50}
                ListHeaderComponent={ListHeader}
                ListFooterComponent={ListFooter}
            />
        </View>
    );
};
